client_script:
frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

$(document).ready(function() {

    var fields = [
        'email_address',
        'candidate_name',
        'candidate_dob',
        'where_did_you_hear',
        'last_class_attended',
        'latest_board_attended',
        'year_of_passing'
    ];

    function getVal(fn) {
        var inp = document.querySelector('[data-fieldname="' + fn + '"] input.input-with-feedback');
        if (inp && inp.value && inp.value.trim()) return inp.value.trim();
        var sel = document.querySelector('[data-fieldname="' + fn + '"] select');
        if (sel && sel.selectedIndex > 0 && sel.value) return sel.value.trim();
        var ta = document.querySelector('[data-fieldname="' + fn + '"] textarea');
        if (ta && ta.value && ta.value.trim()) return ta.value.trim();
        return '';
    }

    function allFilled() {
        for (var i = 0; i < fields.length; i++) {
            if (!getVal(fields[i])) return false;
        }
        return true;
    }

    function updateBtn() {
        var btn = document.querySelector('button.submit-btn');
        if (!btn) return;
        if (allFilled()) {
            btn.classList.add('show-pay-btn');
        } else {
            btn.classList.remove('show-pay-btn');
        }
    }

    function isFutureOrToday(val) {
        if (!val) return false;
        var entered, parts = val.split('-');
        if (parts.length !== 3) return false;
        if (parts[0].length === 4) {
            entered = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
        } else {
            entered = new Date(parseInt(parts[2]), parseInt(parts[0]) - 1, parseInt(parts[1]));
        }
        if (!entered || isNaN(entered.getTime())) return false;
        var today = new Date();
        today.setHours(0, 0, 0, 0);
        return entered >= today;
    }

    var dobAlertShown = false;

    function showDOBError() {
        if (dobAlertShown) return;
        dobAlertShown = true;

        // Remove any existing DOB error box
        $('#dob-error-msg').remove();

        // Inject styled Frappe-like alert below the DOB field
        var html = '<div id="dob-error-msg" style="' +
            'background: #fff2f2;' +
            'border: 1px solid #e74c3c;' +
            'border-left: 4px solid #e74c3c;' +
            'color: #c0392b;' +
            'padding: 10px 14px;' +
            'border-radius: 4px;' +
            'margin-top: 6px;' +
            'font-size: 13px;' +
            'font-weight: 500;' +
            'display: flex;' +
            'align-items: center;' +
            'gap: 8px;' +
            '">' +
            '<span style="font-size:16px;">⚠️</span>' +
            'Date of Birth cannot be today or a future date. Please enter a valid past date.' +
            '</div>';

        var $dobWrapper = $('[data-fieldname="candidate_dob"]').first();
        $dobWrapper.after(html);

        // Auto-remove after 4 seconds
        setTimeout(function() {
            $('#dob-error-msg').fadeOut(400, function() {
                $(this).remove();
                dobAlertShown = false;
            });
        }, 4000);
    }

    function clearDOB(inp) {
        inp.value = '';
        $(inp).val('').trigger('change');
        var ev1 = new Event('input',  { bubbles: true });
        var ev2 = new Event('change', { bubbles: true });
        inp.dispatchEvent(ev1);
        inp.dispatchEvent(ev2);
        setTimeout(updateBtn, 100);
    }

    function checkAndBlockDOB(inp) {
        if (inp && inp.value && isFutureOrToday(inp.value)) {
            clearDOB(inp);
            showDOBError();
        }
    }

    function restrictDOB() {
        var inp = document.querySelector('[data-fieldname="candidate_dob"] input.input-with-feedback');
        if (!inp || inp.__dob) return;
        inp.__dob = true;

        inp.addEventListener('change', function() { checkAndBlockDOB(inp); });
        inp.addEventListener('blur',   function() { checkAndBlockDOB(inp); });
        inp.addEventListener('keyup',  function() {
            if (inp.value && inp.value.length >= 8) checkAndBlockDOB(inp);
        });
    }

    function attach() {
        document.querySelectorAll(
            '[data-fieldname] input,' +
            '[data-fieldname] select,' +
            '[data-fieldname] textarea'
        ).forEach(function(el) {
            if (el.__b) return;
            el.__b = true;
            el.addEventListener('input',  updateBtn);
            el.addEventListener('change', updateBtn);
            el.addEventListener('blur',   updateBtn);
        });
    }

    window.checkFields = function() {
        console.log('===== FIELD CHECK =====');
        fields.forEach(function(fn) {
            var v = getVal(fn);
            console.log((v ? '✅' : '❌'), fn, '->', JSON.stringify(v));
        });
        console.log('allFilled ->', allFilled());
        console.log('=======================');
    };

    console.log('[MV] Script loaded');

    setInterval(function() {
        restrictDOB();
        attach();
        updateBtn();
        var inp = document.querySelector('[data-fieldname="candidate_dob"] input.input-with-feedback');
        if (inp && inp.value && isFutureOrToday(inp.value)) {
            clearDOB(inp);
            showDOBError();
        }
    }, 300);

    setTimeout(function() {
        restrictDOB();
        attach();
        updateBtn();
        console.log('[MV] Boot complete.');
    }, 2000);

});

